// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: Immediately after initialize(...) on the correct contract, paused() == false.
    // The mutant that negates the stored flag will return true instead, so this fuzz test
    // lets the fuzzer pick any nonzero address for lrtConfigAddr to call initialize.
    function testFuzz_property(address lrtConfigAddr) public {
        // keep wide domain but disallow zero address because initialize checks non-zero
        vm.assume(lrtConfigAddr != address(0));

        // Call initialize with the fuzzed address
        c.initialize(lrtConfigAddr);

        // Query paused() and assert it is false on the reference for all inputs.
        // The mutant that negates the stored _paused will return true here for these inputs,
        // causing the test to fail for that mutant for some inputs (in fact any valid address).
        bool p = c.paused();
        assertTrue(p == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz with an address that will act as a MANAGER (caller) for pause.
    // The general rule: paused() returns the actual paused state. We trigger a transition to paused
    // by calling pause() as a manager (we don't need real access control for this test file context;
    // instead we simulate by directly calling pause() from this EOA). The mutated version that
    // always returns false will differ after pause: reference returns true, mutant returns false.
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a sensible actor
        vm.assume(caller != address(0));

        // call pause() as the fuzzed caller. In the reference contract pause() requires onlyLRTManager
        // which checks roles via lrtConfig; in this test environment roles are not set, so calling
        // pause() may revert. To ensure we exercise the pause/unpause behavior without dealing with
        // access control, we instead directly invoke C._pause via calling pause through a prank on
        // the contract owner is not possible; but the reference contract's pause() is public and will
        // revert if caller lacks role. To create an admissible input that succeeds, we instead
        // call c.pause() inside a try/catch: if it succeeds the contract becomes paused and paused()
        // must return true; if it reverts then paused() must remain false. The mutant always returns
        // false so there exists inputs (those where pause() succeeds) that will make the assertion fail.

        bool pausedCallSucceeded;
        // attempt to pause as caller
        vm.prank(caller);
        try c.pause() {
            pausedCallSucceeded = true;
        } catch {
            pausedCallSucceeded = false;
        }

        // Now read paused() and assert the general property: paused() == pausedCallSucceeded
        // In the reference contract: if pause() succeeded, paused() must be true; if pause() failed, paused() must be false.
        // The mutant that always returns false will violate this when pausedCallSucceeded == true.
        bool reportedPaused = c.paused();
        assertTrue(reportedPaused == pausedCallSucceeded);
    }
}

