pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal fake LRTConfig and AccessControl to grant roles for testing
contract FakeAccessControl {
    mapping(bytes32 => mapping(address => bool)) public roles;
    function grantRole(bytes32 role, address account) external {
        roles[role][account] = true;
    }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

contract FakeLRTConfig is FakeAccessControl {
    address public oracle;
    address public rseth;
    mapping(address => bool) public supported;
    mapping(address => uint256) public limits;

    function setSupported(address asset, bool ok, uint256 limit) external {
        supported[asset] = ok;
        limits[asset] = limit;
    }

    function isSupportedAsset(address asset) external view returns (bool) {
        return supported[asset];
    }
    function depositLimitByAsset(address asset) external view returns (uint256) {
        return limits[asset];
    }
    function getContract(bytes32) external view returns (address) { return oracle; }
    function rsETH() external view returns (address) { return rseth; }
    // allow access-control checks by casting to IAccessControl in C
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

contract InvMutTest is Test {
    C c;
    FakeLRTConfig cfg;

    function setUp() public {
        c = new C();
        cfg = new FakeLRTConfig();
    }

    // General rule: after a legitimate manager calls pause(), the contract reports paused() == true.
    // We fuzz the manager address so the fuzzer can find one that has the MANAGER role (we grant it),
    // and assert that paused() becomes true after pause() (reference: holds for all inputs; mutant: fails for some).
    function testFuzz_property(address manager) public {
        // keep domain wide but exclude zero address to be practical
        vm.assume(manager != address(0));

        // configure lrtConfig and give manager the MANAGER role
        // deposit cfg into c by calling updateLRTConfig which requires onlyLRTAdmin in original, but initialize emits UpdatedLRTConfig
        // We need to initialize c to set lrtConfig; call initialize with cfg address
        c.initialize(address(cfg));

        // grant MANAGER role to the fuzzed manager in cfg so onlyLRTManager modifier will accept it
        bytes32 MANAGER = keccak256("MANAGER");
        cfg.grantRole(MANAGER, manager);

        // ensure contract is currently not paused
        bool beforePaused = c.paused();

        // act as the manager and call pause()
        vm.prank(manager);
        c.pause();

        // observe paused() after pause and assert the property
        bool afterPaused = c.paused();

        // Single assertion: in the correct contract, if beforePaused was false then afterPaused must be true
        // This captures that pause() flips the paused state for a valid manager caller; the mutant returning false will violate this for some manager
        assertTrue(!(beforePaused == false) || (afterPaused == true));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the manager address that will call pause(). The rule: if an address is allowed to call pause()
    // (i.e. calling pause() does not revert), then after the call the contract must report paused() == true.
    // The mutant that always returns false will violate this for addresses that can successfully call pause().
    function testFuzz_property(address manager) public {
        // keep the fuzzed address wide but non-zero
        vm.assume(manager != address(0));

        // We need to make the manager able to call pause() without role checks failing.
        // In the reference contract C, onlyLRTManager checks IAccessControl(address(lrtConfig)).hasRole(MANAGER, msg.sender)
        // To bypass external role checks, we set lrtConfig to an address whose IAccessControl.hasRole returns true for our manager.
        // Deploy a helper LRTConfigStub that returns true for hasRole and harmless defaults for required functions.
        LRTConfigStub stub = new LRTConfigStub(manager);

        // Initialize contract with stub as lrtConfig
        c.initialize(address(stub));

        // Ensure the manager has some ETH to avoid low-level issues (not strictly necessary here)
        vm.deal(manager, 1 ether);

        // Call pause() as manager. If the manager is authorized, pause() will succeed; otherwise it will revert.
        bool ok;
        try c.pause{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call to pause() succeeded (ok==true), then c.paused() must return true.
        // The reference satisfies this for all inputs; the mutant that always returns false will fail for some manager
        // where pause() succeeds but paused() returns false.
        if (ok) {
            assertTrue(c.paused());
        } else {
            // If pause() reverted, we cannot assert paused() (the rule quantifies only over successful pause calls),
            // so assertTrue(true) to keep a single assert in the function by encoding as an always-true check when ok==false.
            // However the test framework requires exactly one assertTrue reading c; to comply, we instead assert that paused()==false
            // is not required here — but to follow the requirement of exactly one assert reading c we do:
            // when ok==false, we still call paused() (it must not revert) and assert that paused() == paused() (tautology)
            // to meet the technical constraint that the single assert reads c. We implement this by fetching the value and asserting it's equal to itself.
            bool p = c.paused();
            assertTrue(p == p);
        }
    }
}

// Minimal stub for ILRTConfig and IAccessControl behavior needed by C
contract LRTConfigStub {
    address public managerAllowed;
    constructor(address manager_) {
        managerAllowed = manager_;
    }

    // make lrtConfig.rsETH callable
    function rsETH() external pure returns (address) { return address(0x100); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32) external view returns (address) {
        // return an address for LRT_ORACLE lookups; we return address(this) so getRSETHPrice works
        return address(this);
    }
    function getSupportedAssetList() external pure returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }

    // used by LRTConfigRoleChecker only via IAccessControl interface: hasRole
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == managerAllowed;
    }

    // Oracle functions used by C.getRsETHAmountToMint via returned address
    function getAssetPrice(address) external pure returns (uint256) { return 1 ether; }
    function assetPriceOracle(address) external pure returns (address) { return address(0); }
    function getRSETHPrice() external pure returns (uint256) { return 1 ether; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: address adminCandidate - the fuzzer will search for an address that can call pause() successfully
    function testFuzz_property(address adminCandidate) public {
        // The reference contract requires the caller to have LRT_MANAGER role to call pause().
        // We cannot grant roles here (lrtConfig is not set), but pause() will revert for non-manager callers.
        // We therefore consider the admissible domain: an address that, when acting as msg.sender, either
        // (A) pause() succeeds (and then paused() must return true for the reference), or
        // (B) pause() reverts (then we don't require paused() semantics). We restrict to addresses
        // that are not the zero address to avoid degenerate behavior.
        vm.assume(adminCandidate != address(0));

        // Try to call pause() as adminCandidate and observe whether it succeeds; use try/catch to capture behavior.
        bool pauseSucceeded;
        // Use vm.prank to have adminCandidate be msg.sender
        vm.startPrank(adminCandidate);
        try c.pause() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }
        vm.stopPrank();

        // Now read paused() (it is a public view function). The reference contract guarantees:
        //   For every admissible input (here: any caller address), if pause() succeeded then paused() == true.
        // The mutant always returns false from paused(), so for any caller where pause() succeeded the mutant will differ.
        bool pausedOk;
        try c.paused() returns (bool val) {
            pausedOk = val;
        } catch {
            // If paused() reverts (shouldn't in reference), treat as not OK for this test (pauseSucceeded must be false in reference then)
            pausedOk = false;
        }

        // Assert the general rule: if pause() succeeded, then paused() must be true.
        // This is one assertion that holds for the correct contract for all inputs, and is violated by the mutant for some input.
        assertTrue(!pauseSucceeded || pausedOk);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Minimal fake LRTConfig to satisfy role checker and allow role-like access.
    // We only need it to conform to ILRTConfig interface functions used by C.
    contract FakeLRTConfig {
        address public admin;
        address public manager;
        address public rseth;
        address public oracle;
        mapping(address => bool) public supported;
        mapping(address => uint256) public limits;

        constructor(address _admin, address _manager, address _rseth, address _oracle) {
            admin = _admin;
            manager = _manager;
            rseth = _rseth;
            oracle = _oracle;
        }

        function rsETH() external view returns (address) { return rseth; }
        function assetStrategy(address) external pure returns (address) { return address(0); }
        function isSupportedAsset(address asset) external view returns (bool) { return supported[asset]; }
        function getLSTToken(bytes32) external pure returns (address) { return address(0); }
        function getContract(bytes32) external view returns (address) { return oracle; }
        function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a; return a; }
        function depositLimitByAsset(address asset) external view returns (uint256) { return limits[asset]; }

        // role checker compatibility: implement hasRole to gate manager/admin
        function hasRole(bytes32 role, address account) external view returns (bool) {
            bytes32 MANAGER = keccak256("MANAGER");
            bytes32 DEFAULT_ADMIN_ROLE = 0x00;
            if (role == MANAGER) return account == manager;
            if (role == DEFAULT_ADMIN_ROLE) return account == admin;
            return false;
        }

        // helpers for test to configure supported asset and limits
        function setSupported(address asset, bool v, uint256 limit) external { supported[asset] = v; limits[asset] = limit; }
    }

    // Minimal oracle used by getRsETHAmountToMint; returns constant prices
    contract FakeOracle {
        uint256 public assetPrice = 1 ether;
        uint256 public rsethPrice = 1 ether;
        function getAssetPrice(address) external view returns (uint256) { return assetPrice; }
        function assetPriceOracle(address) external view returns (address) { return address(0); }
        function getRSETHPrice() external view returns (uint256) { return rsethPrice; }
    }

    // Minimal ERC20 to satisfy transfers and balance checks
    contract SimpleToken {
        string public name = "T";
        string public symbol = "T";
        uint8 public decimals = 18;
        mapping(address => uint256) public balanceOf;
        mapping(address => mapping(address => uint256)) public allowance;
        function mint(address to, uint256 amt) external { balanceOf[to] += amt; }
        function approve(address spender, uint256 amt) external returns (bool) { allowance[msg.sender][spender] = amt; return true; }
        function transferFrom(address from, address to, uint256 amt) external returns (bool) {
            if (balanceOf[from] < amt) return false;
            if (allowance[from][msg.sender] < amt) return false;
            balanceOf[from] -= amt;
            allowance[from][msg.sender] -= amt;
            balanceOf[to] += amt;
            return true;
        }
        function transfer(address to, uint256 amt) external returns (bool) {
            if (balanceOf[msg.sender] < amt) return false;
            balanceOf[msg.sender] -= amt;
            balanceOf[to] += amt;
            return true;
        }
    }

    // Minimal rseth token implementing mint used by _mintRsETH
    contract SimpleRSETH is SimpleToken {
        function mint(address to, uint256 amt) external override { balanceOf[to] += amt; }
    }

    function setUp() public {
        c = new C();
    }

    // The property: for any fuzzed manager address and admin address (distinct), when a setup
    // where manager has role and admin has role is performed, calling pause() as manager
    // results in paused() returning true on the correct contract. The mutant that always
    // returns false will make this assertion fail for such inputs.
    function testFuzz_property(address adminAddr, address managerAddr) public {
        // Avoid trivial zero addresses for roles to keep domain wide but valid
        vm.assume(adminAddr != address(0));
        vm.assume(managerAddr != address(0));

        // Deploy helpers
        FakeOracle oracle = new FakeOracle();
        SimpleRSETH rseth = new SimpleRSETH();
        FakeLRTConfig lrt = new FakeLRTConfig(adminAddr, managerAddr, address(rseth), address(oracle));

        // initialize C with lrt config via initializer
        // Only admin can call updateLRTConfig; but initialize uses initializer and updateLRTConfig emits event
        // We call initialize directly (no access restriction)
        c.initialize(address(lrt));

        // Ensure manager can call pause(): our FakeLRTConfig reports manager has MANAGER role
        // Call pause as managerAddr
        vm.prank(managerAddr);
        c.pause();

        // Observe paused() via public getter; reference should return true, mutant returns false
        bool ok;
        try c.paused() returns (bool val) {
            ok = val;
        } catch {
            ok = false;
        }

        // Single assertion: the correct contract yields paused()==true for these inputs
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We need an admin account that has the DEFAULT_ADMIN_ROLE in the referenced setup.
    // The contract's onlyLRTAdmin modifier checks IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
    // In absence of a real lrtConfig we exploit initializer to set a dummy non-zero lrtConfig first via initialize,
    // then use updateLRTConfig to attempt to set address(0). The reference will revert on zero address, the mutant will accept it.

    function setUp() public {
        c = new C();
        // deploy a minimal dummy LRTConfig-like contract that reports msg.sender has admin role
        DummyLRTConfig dummy = new DummyLRTConfig();
        // initialize c with dummy lrtConfig address (non-zero)
        c.initialize(address(dummy));
        // mark dummy to grant DEFAULT_ADMIN_ROLE to this test contract (msg.sender for calls will be this test contract)
        dummy.grantAdmin(address(this));
    }

    // fuzz the input address to let fuzzer find address(0) if needed; property: calling updateLRTConfig with zero should revert
    function testFuzz_property(address newAddr) public {
        // keep wide: no vm.assume to allow zero address
        bool ok;
        try c.updateLRTConfig(newAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        // The universal property: for all inputs, if newAddr == address(0) then reference should revert (ok==false).
        // We assert that update with zero address does NOT succeed. This holds on reference (reverts) and fails on mutant (succeeds),
        // and we encode it as a single assertion over the contract's observed behavior.
        if (newAddr == address(0)) {
            assertTrue(!ok);
        } else {
            // for non-zero addresses, update may succeed; assert nothing about them besides a tautology via reading c
            // To keep exactly one assertTrue overall, we still assert that when newAddr != 0 the call either succeeds or fails
            // but we must use a single assertion in the test. So we combine into one boolean:
            assertTrue(ok || !ok);
        }
    }
}

// Minimal dummy that imitates an ILRTConfig and simplest AccessControl behaviour for DEFAULT_ADMIN_ROLE
contract DummyLRTConfig {
    address public admin;
    function grantAdmin(address a) external {
        admin = a;
    }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function getContract(bytes32) external view returns (address) { return address(this); }
    function rsETH() external pure returns (address) { return address(0x123); }
    // mimic AccessControl hasRole for DEFAULT_ADMIN_ROLE (0x00)
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == admin;
    }
}

