pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal mock of ILRTConfig and IAccessControl to set roles and allow admin to call
interface IMockLRTConfig {
    function rsETH() external view returns (address);
}

contract MockAccessControlledConfig {
    // expose functions used by C
    function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
    function getContract(bytes32) external view returns (address) { return address(this); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function rsETH() external pure returns (address) { return address(0x123); }
}

// Minimal AccessControl mock: allow the test caller to be admin/manager based on who calls
contract MockAccessControl is MockAccessControlledConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;
    // allow test to set roles
    function setRole(bytes32 role, address who, bool val) external { roles[role][who] = val; }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

contract InvMutTest is Test {
    C c;
    MockAccessControl mockConfig;

    function setUp() public { c = new C(); }

    // The fuzzer supplies an admin address; we will make that address hold the DEFAULT_ADMIN_ROLE (0x00)
    // The property: for any admin address, trying to set lrtConfig to address(0) should revert on the reference.
    // We fuzz the admin address to let the fuzzer find one that exposes the mutant behavior (mutant will accept address(0)).
    function testFuzz_property(address admin) public {
        // keep admin non-zero to be a realistic caller (but still allow any address)
        vm.assume(admin != address(0));

        // deploy and register a mock config address; the real contract's updateLRTConfig expects an ILRTConfig address
        mockConfig = new MockAccessControl();

        // grant admin the DEFAULT_ADMIN_ROLE (0x00) in the mock access control so onlyLRTAdmin passes
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        mockConfig.setRole(DEFAULT_ADMIN_ROLE, admin, true);

        // Now call updateLRTConfig as admin with address(0) and observe whether it reverted or not.
        bool ok;
        vm.prank(admin);
        try c.updateLRTConfig(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERT: on the correct contract, updateLRTConfig(address(0)) must revert for every admin.
        // This assert will be true for the reference and will fail for the mutant for some admin (the fuzzer will find one).
        assertTrue(!ok);
    }
}

