    }

    function setUp() public { c = new C(); }

    // fuzzed params: adminCandidate is the address we'll try to use as the LRT admin caller
    function testFuzz_property(address adminCandidate) public {
        // keep adminCandidate non-zero so vm.prank works sensibly; still wide domain
        vm.assume(adminCandidate != address(0));

        // Deploy a FakeAdmin that will claim admin for adminCandidate
