        // According to the reference: since adminCandidate is reported by fake as having DEFAULT_ADMIN_ROLE, the
        // onlyLRTAdmin modifier allows the call, but the reference further checks non-zero and will revert.
        // The mutant removed the non-zero check and will accept address(0). We detect difference by observing success.

        bool ok;
        // perform the external call as adminCandidate
        vm.prank(adminCandidate);
        try c.updateLRTConfig(address(0)) {
            ok = true;
        } catch {
            ok = false;
