// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the lrtConfigAddr which initialize() accepts. The correct contract must always
    // set maxNodeDelegatorCount to 10 for any non-zero address passed to initialize.
    function testFuzz_property(address lrtConfigAddr) public {
        // admissible domain: lrtConfigAddr must be non-zero (initializer checks this via UtilLib)
        vm.assume(lrtConfigAddr != address(0));

        // Call initialize with the fuzzed address and then assert the invariant about maxNodeDelegatorCount.
        // Use try/catch to ensure the test still reads the post-state even if initialize reverts
        // (but for the correct contract it should succeed and set value to 10).
        bool ok;
        try c.initialize(lrtConfigAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always succeeds (does not revert) and sets maxNodeDelegatorCount to 10.
        // The single assertion reads the contract's public getter for maxNodeDelegatorCount.
        // This will pass on the reference for all nonzero lrtConfigAddr and fail on the mutant for some inputs.
        assertTrue(ok && c.maxNodeDelegatorCount() == 10);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter is the lrtConfig address passed to initialize
    function testFuzz_property(address lrtConfigAddr) public {
        // admissible domain: non-zero config address (initializer requires non-zero)
        vm.assume(lrtConfigAddr != address(0));

        // Try calling initialize with the fuzzed address and observe whether maxNodeDelegatorCount becomes 10
        bool ok;
        try c.initialize(lrtConfigAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always sets maxNodeDelegatorCount to 10 after initialize returns successfully.
        // We assert that either initialize reverted (ok == false) or, if it returned, the maxNodeDelegatorCount is 10.
        // This rule is satisfied by the reference for all admissible inputs; the mutant can return while leaving
        // maxNodeDelegatorCount at 0 for some lrtConfigAddr, causing the assertion to fail.
        if (ok) {
            assertTrue(c.maxNodeDelegatorCount() == 10);
        } else {
            // if initialize reverted, still accept as admissible (reference may revert on bad addresses);
            // ensure we don't assert on maxNodeDelegatorCount in this branch
            assertTrue(true);
        }
    }
}
